#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a UObject (UArenaScoreTracker) created via NewObject<UArenaScoreTracker>(this) in BeginPlay() and stored as a raw pointer without UPROPERTY(). Because Outer ownership does not prevent Unreal garbage collection, the periodic GC pass (~60s into play, logged at 21.05.13) purges ScoreTracker and leaves a dangling pointer; the next AArenaGameMode::OnGoalScored() call invokes ScoreTracker->AddPoints(), causing EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff.",
  "no_colors_cause": "AArenaGameMode::BeginPlay() dynamically loads /Game/Data/Palettes/DA_Primary via a hardcoded string path in LoadObject<UArenaPalette>(), which the Unreal cooker cannot discover via static asset references. With bCookAll=False in Config/DefaultGame.ini, DirectoriesToAlwaysCook lists /Game/Data/Effects but omits /Game/Data/Palettes, so DA_Primary is excluded from the packaged pak file (while present on disk in the editor). LoadObject() fails at runtime, returns nullptr, and Hud->ApplyPalette(nullptr) falls back to gray."
}
